"""258 original MCQs complete six 100-question foundation weeks."""
import collections,contextlib,io,json,pathlib,subprocess,textwrap
ROOT=pathlib.Path(__file__).resolve().parents[1]
questions=[];week=1;topic='types'
def Q(title,code,correct,wrong,explanation,mode='concept'):
    pos=len(questions)%4;options=list(wrong);options.insert(pos,correct)
    assert len(options)==4 and len(set(options))==4,(week,title,options)
    code=textwrap.dedent(code).strip()
    if mode=='python-output':
        out=io.StringIO()
        with contextlib.redirect_stdout(out):exec(compile(code,'foundation-reference','exec'),{})
        assert out.getvalue().rstrip('\n')==correct,(title,out.getvalue(),correct)
    questions.append(dict(id=f'foundation-w{week}-{sum(q["week"]==week for q in questions)+1:03}',week=week,topic=topic,bank='foundation-new',title=title,code=code,options=options,answer=pos,explanation=explanation,mode=mode,source=f'Week {week} · Original foundation practice'))
def C(name,code,correct,wrong,explanation):Q(name+' — what is printed?',code,correct,wrong,explanation,'python-output')
def T(title,correct,wrong,explanation):Q(title,'',correct,wrong,explanation)
# Week 1: 48 additions to 52 retained questions.
C('Retaining an earlier binding','flow = 8\nold_flow = flow\nflow = 11\nprint(old_flow, flow)','8 11',['11 11','8 8','11 8'],'Rebinding flow does not change the separate old_flow binding.')
C('Numeric text conversion','raw = "007"\nvalue = int(raw)\nprint(value, type(value).__name__)','7 int',['007 str','7.0 float','007 int'],'int parses the text as an integer; leading zeros do not remain in its numeric display.')
C('A true quotient','print(9 / 4)','2.25',['2','2.0','1'],'Python / computes a true quotient rather than integer floor division.')
C('A floor quotient and remainder','print(17 // 5, 17 % 5)','3 2',['3.4 2','2 3','4 2'],'17 contains three complete groups of five and a remainder of two.')
