week=2;topic='decisions'
C('A two-way temperature decision','temperature = 15\nif temperature >= 20:\n    print("warm")\nelse:\n    print("cool")','cool',['warm','15','No output'],'The condition is false, so only the else suite runs.')
C('An equality boundary in elif','x = 10\nif x < 10:\n    print("low")\nelif x == 10:\n    print("edge")\nelse:\n    print("high")','edge',['low','high','low\nedge'],'The first branch is false and the equality branch is true.')
C('First matching classification','score = 85\nif score >= 80:\n    print("A")\nelif score >= 60:\n    print("B")','A',['B','A\nB','No output'],'An if/elif chain stops after its first true branch.')
C('Independent conditions','x = 6\nif x > 0:\n    print("positive")\nif x % 2 == 0:\n    print("even")','positive\neven',['positive','even','No output'],'These are independent if statements; both conditions are true.')
C('A conjunction of constraints','mass, cost = 4, 12\nprint(mass <= 5 and cost <= 10)','False',['True','4','12'],'The mass passes, but both constraints are required and cost fails.')
C('An alternative trigger','pressure, temperature = 8, 95\nprint(pressure > 10 or temperature > 90)','True',['False','95','8'],'Only one true operand is needed for this or expression.')
C('Negating a condition','running = False\nprint(not running)','True',['False','None','0'],'not reverses the Boolean truth value.')
C('A nested branch','x, y = 3, -2\nif x > 0:\n    if y > 0:\n        print("both")\n    else:\n        print("x only")','x only',['both','No output','x only\nboth'],'The outer condition passes, but the inner condition selects its else suite.')
C('A range with a step','print(list(range(2, 10, 3)))','[2, 5, 8]',['[2, 5, 8, 11]','[2, 3, 10]','[3, 6, 9]'],'Starting at two and adding three stops before reaching or passing ten.')
C('A descending loop','for i in range(3, 0, -1):\n    print(i)','3\n2\n1',['3\n2\n1\n0','0\n1\n2','3\n0'],'The negative step counts down while excluding the stop value zero.')
C('Summing a nonzero range','total = 0\nfor i in range(2, 6):\n    total += i\nprint(total)','14',['15','4','6'],'The values two through five contribute 2+3+4+5.')
C('Counting selected values','count = 0\nfor x in [2, 7, 4, 9]:\n    if x > 5:\n        count += 1\nprint(count)','2',['4','3','1'],'Only seven and nine satisfy the condition.')
C('Break before accumulation','total = 0\nfor x in [3, 5, 0, 9]:\n    if x == 0:\n        break\n    total += x\nprint(total)','8',['17','0','3'],'The stop marker ends the loop before it or the later value enters the sum.')
C('Continue skips one iteration','out = []\nfor i in range(5):\n    if i == 2:\n        continue\n    out.append(i)\nprint(out)','[0, 1, 3, 4]',['[0, 1]','[0, 1, 2, 3, 4]','[1, 3, 4]'],'continue skips the append for two, then the loop proceeds.')
C('A while counter','n = 1\nwhile n < 9:\n    n *= 2\nprint(n)','16',['8','9','18'],'The updates produce two, four, eight and sixteen; sixteen is the first value not below nine.')
C('A bounded decrement','n = 10\nsteps = 0\nwhile n > 0:\n    n -= 4\n    steps += 1\nprint(n, steps)','-2 3',['2 2','0 3','-2 4'],'Three updates produce six, two and minus two.')
C('Zero loop passes','value = 5\nwhile value < 0:\n    value += 1\nprint(value)','5',['0','6','No output'],'The condition is false before the first pass, so the body never runs.')
C('A product accumulator','product = 1\nfor x in [2, 3, 4]:\n    product *= x\nprint(product)','24',['9','0','12'],'The multiplicative identity one allows all three factors to contribute.')
C('Nested iteration count','count = 0\nfor i in range(2):\n    for j in range(3):\n        count += 1\nprint(count)','6',['5','3','2'],'Two outer passes each contain three inner passes.')
C('The last loop binding','for value in [4, 6, 8]:\n    pass\nprint(value)','8',['4','6','None'],'The loop variable remains bound to the last item after this nonempty loop.')
C('String membership condition','label = "pump-A"\nprint("pump" in label, "B" in label)','True False',['True True','False False','False True'],'The substring pump is present; B is absent.')
C('A conditional expression','x = -3\nprint("negative" if x < 0 else "nonnegative")','negative',['nonnegative','-3','True'],'The true condition selects the expression before else.')
C('A parity branch','n = 14\nif n % 2:\n    print("odd")\nelse:\n    print("even")','even',['odd','0','14'],'The remainder is zero, which is false in the if condition.')
C('An accumulated string','result = ""\nfor letter in "AB":\n    result += letter * 2\nprint(result)','AABB',['ABAB','AB','AAAA'],'Each character is doubled before being appended to the growing text.')
C('A loop else after completion','for x in [1, 2]:\n    if x == 9:\n        break\nelse:\n    print("not found")','not found',['9','No output','1\n2'],'The loop finishes without break, so its else suite runs.')
C('A loop else after break','for x in [1, 2]:\n    if x == 2:\n        print("found")\n        break\nelse:\n    print("missing")','found',['found\nmissing','missing','No output'],'The break suppresses the loop else suite.')
