ROOT.joinpath('dist/first-half-bank.js').write_text('// Original additions preserve the earlier 342 question objects and IDs.\nconst FIRST_HALF_WEEKS = '+json.dumps(weeks,ensure_ascii=False)+';\nconst FOUNDATION_ADDITIONS = '+json.dumps(questions,ensure_ascii=False,indent=2)+';\nMCQS.push(...FOUNDATION_ADDITIONS);\nconst FIRST_HALF_MCQS = MCQS.filter(q=>q.bank!=="second-half");\nfunction firstWeek(q){return q.week || ({types:1,arithmetic:1,engineering:1,decisions:2,for:2,while:2,strings:3,functions:4,lists:5,dicts:6,recursion:6})[q.topic];}\n',encoding='utf8')
